-- chapter:2
UPDATE content_text SET text = '{"prologue":[{"kind":"log","text":"Đây là đêm đầu tiên Kai ở ngoài Vùng Tối. Sau lưng anh, thành phố vẫn sáng đèn theo đúng nhịp OMNI đặt ra."},{"kind":"log","text":"Từ Vùng Tối ra tới biên giới mất gần hết đêm. Giữa thành phố và vùng đất bên ngoài là Vành Sentinel."},{"kind":"log","text":"Vành Sentinel là dải đất rộng chừng một cây số, nằm giữa tường thành phố và rào ngoại vi. Drone tuần tra ở đó theo luật cố định, không có người trực. Ai vào mà không có lệnh của OMNI đều bị xử lý."},{"kind":"kai","text":"Neural-ID giả của tôi chỉ sống tới đợt quét lớn lúc rạng sáng. Tôi phải qua bên kia trước giờ đó."},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Rào ngoài hở lúc 03:41. Drone đổi ca lúc 03:47. Tôi đã tính sẵn cho bạn.\""},{"kind":"echo","text":"Lịch đó không đi qua trạm nào của Mạng Mù. Tôi không kiểm tra được nó… Đừng đi theo."},{"kind":"kai","text":"Tôi sẽ không đi theo lịch của ai. Muốn qua được, tôi phải tự biết drone sẽ làm gì."},{"kind":"echo","text":"Drone không đoán. Nó so sánh, rồi chọn… Bạn hãy đọc luật của chúng trước, rồi viết luật của mình."},{"kind":"echo","text":"Ta sẽ dựng một bộ luật né gồm sáu luật. Qua mỗi chặng, bạn thêm một luật."},{"kind":"log","text":"Dưới chân rào ngoại vi có một ống thoát nước. Trong lòng ống, đèn của một drone hỏng vẫn còn nhấp nháy."},{"kind":"card","text":"CHƯƠNG 2\nTRẠM SENTINEL"}],"teaser":[{"kind":"log","text":"Kai đã đứng ở bên kia rào ngoại vi. Thành phố giờ chỉ còn là một vệt sáng sau lưng anh."},{"kind":"echo","text":"Bộ luật né đã đủ sáu luật. Đợt quét lớn vừa đi qua… Neural-ID giả đã tắt. Từ giờ bạn không còn danh tính nào."},{"kind":"log","text":"Hai mảnh trong tám đã về tay. Sáu mảnh còn lại vẫn nằm ở sáu nơi không ai biết."},{"kind":"log","text":"Phía trước là một trung tâm dữ liệu bỏ hoang. Trong hành lang của nó, cảm biến quét đi quét lại, không lúc nào dừng."},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Mảnh thứ ba ở trung tâm dữ liệu cũ. Lần này tôi sẽ đi cùng bạn.\""},{"kind":"echo","text":"Phía trước không còn trạm nào của Mạng Mù. Từ đây, tôi chỉ biết những gì bạn nhìn thấy."},{"kind":"log","text":"GÓI TIN CUỐI CÙNG TRƯỚC KHI NEURAL-ID GIẢ TẮT\nNHẬT KÝ CỔNG KIỂM SOÁT · NX-0417\nMỨC TUÂN THỦ: 100% → 96%\nĐÃ ĐƯA VÀO DANH SÁCH THEO DÕI"},{"kind":"kai","text":"Nhi bị theo dõi là vì tôi."},{"kind":"card","text":"HẾT CHƯƠNG 2 · TRẠM SENTINEL\nChương 3: Mê cung Máy chủ\nTín hiệu đang giải mã."}]}', revision = 2, updated_at = '2026-11-06T00:00:00.000Z', updated_by = 'migration' WHERE doc_id = 'chapter:2' AND revision = 1 AND updated_by = 'migration';
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'chapter:2' AND revision = 2 AND updated_at = '2026-11-06T00:00:00.000Z' AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;

-- level:2.1
UPDATE content_text SET text = '{"location":"Đường Ống Số 9","briefing":"[NHẬT KÝ CHIP LUẬT – D-31]\nD-31 là drone tuần tra của Vành Sentinel. Nó rơi xuống ống thoát nước dưới rào ngoại vi và nằm kẹt ở đó. Cánh quạt đã hỏng, nhưng chip luật vẫn chạy và vẫn đọc cảm biến.\nTrước mỗi quyết định, chip lấy bốn số đo từ cảm biến rồi tính ra ba cờ. Mỗi cờ chỉ có hai giá trị: đúng hoặc sai.\nKai cần tính lại ba cờ ấy theo đúng cách như chip tính.","task_steps":["Bốn số đo `khoang_cach`, `tam_quet`, `che_do`, `pin` ở dòng khóa là dữ liệu cảm biến. Không sửa 4 dòng đó.","Mỗi cờ là kết quả của đúng một phép so sánh và phải có kiểu `bool`. Đọc kỹ luật ở ô Mục tiêu, nhất là chữ \"không vượt quá\" và chữ \"dưới\".","Bạn không cần in gì: sau mỗi lượt chạy, terminal đã hiện giá trị và kiểu của ba cờ.","Bấm CHẠY. Hoàn thành khi cả 3 mục tiêu chuyển thành xanh ở mọi tình huống. Dùng không quá 3 câu lệnh và qua được lượt OMNI đổi số đo thì được thêm sao."],"objectives":[{"var":"trong_tam","label":"Trong tầm: đúng khi khoảng cách không vượt quá tầm quét"},{"var":"dang_quet","label":"Đang quét: đúng khi chế độ là chuỗi QUET, khớp từng ký tự"},{"var":"het_pin","label":"Hết pin: đúng khi pin dưới 20"}],"hints":["Nhìn dòng 10 trước: số 20 nằm trong ngoặc kép nên nó là chữ, không phải số. Rồi nhìn dòng 9: một dấu `=` là đặt giá trị vào biến, không phải hỏi hai thứ có bằng nhau không.","Một phép so sánh tự nó đã là câu trả lời đúng hoặc sai. Gán thẳng nó vào cờ, không cần thêm lệnh nào.\nĐọc từng chữ của luật. \"Không vượt quá\" vẫn đúng khi hai số bằng nhau. \"Dưới\" thì bắt buộc phải dưới, không được bằng.\nTính tay ba cờ với số đo trên dòng khóa, rồi so với những gì terminal hiện ra.","Mảnh tài liệu Python còn đọc được:\n12 == 8   → False   (bằng)\n12 != 8   → True    (khác)\n12 < 8    → False   (nhỏ hơn)\n12 > 8    → True    (lớn hơn)\n12 <= 8   → False   (nhỏ hơn hoặc bằng)\n12 >= 8   → True    (lớn hơn hoặc bằng)\n5 < 5 → False, nhưng 5 <= 5 → True.\nx = 5 là gán, x == 5 là so sánh.\n\"Lan\" == \"lan\" → False: chuỗi so từng ký tự, phân biệt hoa thường.\n3 < \"4\" → TypeError: không so lớn nhỏ giữa số và chuỗi được."],"reactions":{"entry":"Đường Ống Số 9. D-31 kẹt ở đây, nhưng chip luật vẫn tính. Ba cờ này là những gì drone thấy trước khi quyết định. Chạy một lần… rồi nhìn ba đèn.","TypeError":"Dòng {line}. TypeError. Chip đang so một con số với một thứ chỉ trông giống số. Hai kiểu khác nhau thì không so lớn nhỏ được.","type_mismatch":"Ở tình huống {round}, cờ {vars} không giữ giá trị đúng sai. Dòng gán cờ đó đặt một giá trị vào… chứ không hỏi gì cả.","type_mismatch_value_match":"Cờ {vars} ghi đúng chữ, nhưng đó là chữ nằm trong ngoặc kép. Chip chỉ đọc giá trị đúng sai thật, kiểu `bool`.","wrong_value":"Cờ {vars} lệch với chip ở tình huống {round}. Nhìn số đo của tình huống đó… nhất là chỗ hai số chạm nhau.","missing_var":"Ở tình huống {round}, chip chờ cờ {vars} mà không thấy. Đèn đó vẫn tắt.","SyntaxError":"Dòng {line}. Trình dịch không hiểu cấu trúc này. Chip chưa tính được cờ nào.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng… cũng là ngữ pháp.","ValueError":"Dòng {line}. ValueError. Giá trị này không có kiểu mà phép tính cần.","NameError":"Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có. Soát từng ký tự… nhất là tên các cảm biến.","ZeroDivisionError":"Dòng {line}. Chia cho không. Chip không tính tiếp được.","AttributeError":"Dòng {line}. AttributeError. Dữ liệu này không có thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Đọc dòng truy vết.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi OMNI lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ngoài Vùng Tối, ta cũng chỉ có những gì đang cầm trong tay.","input_unsupported":"Không có ai ở đầu kia để trả lời. Số đo đã nằm sẵn trên dòng khóa.","system_exit":"Chương trình tự dừng giữa chừng. Chip không nhận được cờ nào.","alert_exceeded":"Ba cờ khớp chip. Nhưng {count} câu lệnh… mỗi lệnh là một lần drone có thể nghe thấy. Tính gọn hơn.","counter_ValueError":"OMNI đổi số đo. Dòng {line} lỗi: ValueError. Số đo mới có kiểu bạn chưa lường tới.","counter_error":"OMNI đổi số đo. Dòng {line}: {error_type}. Mã không chạy được với dữ liệu mới.","counter_type_mismatch":"Số đo mới đi qua mã của bạn… và cờ {vars} ra sai kiểu. Chip không đọc được.","wrong_value_counter":"OMNI đổi số đo, nhưng cờ {vars} không đổi theo. Luật của bạn bám vào số cũ… không bám vào cảm biến.","counter_timeout":"OMNI đổi số đo. Mã của bạn treo với dữ liệu mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Lối qua mở một nửa. Drone chưa nhận ra bạn.","three_stars":"OMNI đổi số đo, mà ba cờ vẫn khớp chip. Giờ ta biết drone nhìn thấy gì.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay bạn.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại luật ở ô Mục tiêu, rồi nhìn ba đèn."},"reaction_variants":{"wrong_value":"Cờ {vars} vẫn lệch ở tình huống {round}. Nhìn đèn đỏ trên bảng tình huống, rồi đọc lại từng chữ của luật đó.","type_mismatch":"Cờ {vars} vẫn sai kiểu ở tình huống {round}. Nhìn màu đèn đó: nó không mang màu của kiểu `bool`.","TypeError":"Vẫn dòng {line}. Một bên là số, bên kia là chữ. Nhìn kỹ dấu ngoặc kép."},"counter_attack_banner":"CẢNH BÁO: OMNI ĐẨY D-31 SANG CHẾ ĐỘ TUẦN TRA VÀ NỚI TẦM QUÉT","outro":"Ba cờ của Kai khớp với chip. D-31 mở thêm một vùng nhớ cũ. Trong đó có một ghi chú của người đã viết luật cho drone:","lore_fragment":"KTS-02: Tôi viết luật cho drone. Mỗi luật chỉ là một phép so sánh: số này với số kia, chữ này với chữ kia. Người ta hỏi tôi drone có ghét ai không. Không. Drone không ghét ai cả. Drone chỉ làm đúng việc nó được giao.","component":"Cảm biến tầm quét","outro_beats":[{"kind":"log","text":"BẢN GHI CUỐI CỦA D-31\nMục tiêu đứng đúng ở mép tầm quét. D-31 bỏ qua.\nTrạm Sentinel đánh giá: vi phạm luật. Đã bắn hạ."},{"kind":"echo","text":"Sentinel làm đúng luật… kể cả với drone của chính nó."},{"kind":"kai","text":"Sentinel bắn hạ cả drone của nó. Nó sẽ không tha cho tôi."},{"kind":"log","text":"Phía trên ống là Hàng Rào Ngoại Vi. Drone bay dọc rào theo một chu kỳ cố định, đêm nào cũng vậy."}],"knowledge_summary":{"title":"Phép so sánh và kiểu bool","sections":[{"heading":"Sáu phép so sánh","body":"Python có sáu phép so sánh: bằng `==`, khác `!=`, nhỏ hơn `<`, lớn hơn `>`, nhỏ hơn hoặc bằng `<=`, lớn hơn hoặc bằng `>=`. Mỗi phép cho ra `True` hoặc `False`."},{"heading":"Kết quả là `bool`","body":"Kết quả của một phép so sánh có kiểu `bool`. Bạn gán thẳng kết quả đó vào biến, không cần thêm lệnh nào."},{"heading":"Điểm bằng nhau","body":"`<` và `<=` chỉ khác nhau khi hai số bằng nhau: `5 < 5` là `False`, còn `5 <= 5` là `True`. Đọc luật bằng lời để chọn phép: \"không vượt quá\" là `<=`, \"dưới\" là `<`."},{"heading":"`=` và `==`","body":"`=` gán giá trị cho biến, `==` so sánh hai giá trị. Viết nhầm `=` thay `==` không phải lúc nào cũng báo lỗi: `a = b = \"X\"` gán `\"X\"` cho cả hai biến."},{"heading":"So sánh chuỗi","body":"`==` so hai chuỗi từng ký tự một, phân biệt chữ hoa với chữ thường. Một dấu cách thừa cũng làm hai chuỗi khác nhau."}],"mistakes":[{"code":"8 < \"9\"","explain":"`\"9\"` nằm trong ngoặc kép nên là chuỗi. Python không so lớn nhỏ giữa số và chuỗi. Bỏ ngoặc kép: `8 < 9`."},{"code":"x = (y = 1)","explain":"`=` là lệnh gán, không cho ra giá trị nên không đặt được trong ngoặc. Muốn so sánh thì viết `==`."},{"code":"co = \"True\"","explain":"Có ngoặc kép thì `\"True\"` là chuỗi bốn ký tự. Giá trị `bool` viết không có ngoặc: `co = True`, hoặc gán thẳng một phép so sánh."},{"code":"a <= b == True","explain":"Python đọc dòng này là so sánh nối: `a <= b and b == True`, không phải \"kết quả của `a <= b` có là `True` không\". Chỉ cần viết `a <= b`."}],"next":"Màn sau dùng một cờ đúng sai để quyết định có chạy một lệnh hay không: câu lệnh `if`."}}', revision = 2, updated_at = '2026-11-06T00:00:00.000Z', updated_by = 'migration' WHERE doc_id = 'level:2.1' AND revision = 1 AND updated_by = 'migration';
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.1' AND revision = 2 AND updated_at = '2026-11-06T00:00:00.000Z' AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;

-- level:2.2
UPDATE content_text SET text = '{"location":"Hàng Rào Ngoại Vi","briefing":"[NHẬT KÝ CẢM BIẾN – HÀNG RÀO NGOÀI]\nMột drone bay dọc hàng rào theo chu kỳ. Mỗi lượt bay qua, nó đo khoảng cách tới Kai rồi so với tầm quét của nó.\nKai cần một lệnh cho mỗi lượt: đi hoặc nấp. Mặc định là đi.\nLệnh chỉ đổi thành nấp khi drone đang ở trong tầm quét, tức là khi khoảng cách không vượt quá tầm quét. Mỗi drone có một tầm quét riêng.","task_steps":["Bấm CHẠY một lần và đọc dòng Python báo lỗi. Dòng nằm ngay dưới `if` phải lùi vào thì mới thuộc về `if` đó.","Biến `lenh` giữ lệnh của Kai. Nó có một giá trị mặc định và chỉ đổi khi drone ở trong tầm quét. Luật đầy đủ nằm ở ô Mục tiêu.","Sau mỗi lượt chạy, xem dòng nào bị làm mờ trong editor: đó là dòng không chạy ở tình huống đang hiện. Xét kỹ tình huống drone đứng đúng mép tầm quét.","Hoàn thành khi mục tiêu chuyển thành xanh ở cả ba tình huống. Dùng không quá 3 câu lệnh và qua được lượt OMNI đổi tầm quét thì được thêm sao."],"objectives":[{"var":"lenh","label":"Lệnh của Kai: `NAP` khi khoảng cách không vượt quá tầm quét, còn lại `DI`"}],"hints":["Python báo lỗi ở dòng 8. Một dòng nằm dưới `if` phải lùi vào 4 dấu cách thì mới thuộc khối của `if` đó. Sửa xong, đọc điều kiện ở dòng 7 thành lời: nó đang hỏi drone ở trong tầm quét hay ở ngoài tầm quét?","Gán lệnh mặc định trước. Sau đó kiểm điều kiện, và trong khối của nó gán lệnh còn lại. Thứ tự hai lệnh gán quyết định kết quả.\nSau mỗi lượt, xem dòng nào bị làm mờ trong editor: dòng mờ là dòng không chạy ở tình huống đó. Xét riêng tình huống drone đứng đúng mép tầm quét, như ở bài trước.\nlệnh = đi\nnếu drone ở trong tầm quét (kể cả đứng đúng mép):\n    lệnh = nấp","Mảnh tài liệu Python còn đọc được:\nif dieu_kien:\n    lenh_1\n    lenh_2\nDòng `if` kết thúc bằng dấu `:`. Khối là các dòng lùi vào 4 dấu cách ngay bên dưới. Khối chỉ chạy khi điều kiện là `True`.\nve = \"THUONG\"\nif tuoi >= 60:\n    ve = \"MIEN PHI\"\nGán giá trị mặc định trước `if`, rồi gán đè trong khối.\nThân `if` không lùi vào → IndentationError: expected an indented block after ''if'' statement on line …"],"reactions":{"entry":"Hàng Rào Ngoại Vi. Lần này luật là của Kai, không phải của OMNI nữa. Chạy một lần… rồi đọc xem Python nói gì.","wrong_branch":"Mã đã đi một đường có thật… nhưng là đường dành cho một tình huống khác. Xem drone bắt được Kai ở tình huống nào. Dòng bị làm mờ trong editor là dòng đã không chạy.","type_mismatch":"Ở tình huống {round}, {vars} đang giữ một giá trị đúng hoặc sai, không phải một lệnh. Chip của Kai chỉ nhận lệnh bằng chữ.","type_mismatch_value_match":"{vars} có đúng chữ cần có, nhưng sai kiểu. Chip của Kai vẫn từ chối.","wrong_value":"Ở tình huống {round}, chip của Kai nhận một lệnh mà drone không hiểu. Lệnh phải đúng từng ký tự như ở ô Mục tiêu, kể cả chữ hoa.","missing_var":"Ở tình huống {round}, Kai không nhận được lệnh nào. Có một đường chạy qua mã mà {vars} chưa từng được gán.","SyntaxError":"Dòng {line}. Python không đọc được dòng này, nên chưa câu lệnh nào chạy. Đọc dòng Python báo trong terminal.","IndentationError":"Dòng {line}. Python không biết dòng này có thuộc về điều kiện phía trên hay không. Một khối lệnh phải nhìn ra được là khối.","TypeError":"Dòng {line}. TypeError. Phép tính vừa nhận một giá trị sai kiểu. Cảm biến không đọc được.","ValueError":"Dòng {line}. ValueError. Giá trị này không dùng được cho phép tính đó.","NameError":"Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có. Soát từng ký tự… nhất là tên các số đo của cảm biến.","ZeroDivisionError":"Dòng {line}. Chia cho không. Python dừng chương trình ngay tại đó.","AttributeError":"Dòng {line}. AttributeError. Dữ liệu này không mang thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Đọc dòng truy vết.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi drone lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở đây, ta chỉ có những gì đang cầm trong tay.","input_unsupported":"Không có ai ở đầu kia để trả lời. Số đo đã nằm sẵn trên cảm biến.","system_exit":"Chương trình tự dừng giữa chừng. Kai không nhận được lệnh nào.","alert_exceeded":"Lệnh đúng. Nhưng {count} câu lệnh… mỗi lệnh là một lần drone có thể nghe thấy. Viết gọn hơn.","counter_ValueError":"OMNI đổi drone. Dòng {line} lỗi: ValueError. Số đo mới mang giá trị bạn chưa lường tới.","counter_error":"OMNI đổi drone. Dòng {line}: {error_type}. Mã không chạy được với số đo mới.","counter_type_mismatch":"Drone mới đi qua mã của bạn… và {vars} ra sai kiểu. Chip của Kai không đọc được.","wrong_value_counter":"OMNI đổi drone, mà lệnh của Kai không đổi theo. Chip nhận một lệnh không có trong luật.","counter_timeout":"OMNI đổi drone. Mã của bạn treo với số đo mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Lối qua mở một nửa. Kai qua mà không để lại dấu vết.","three_stars":"Drone đổi, luật của Kai vẫn đúng. Lối qua mở hẳn.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại cảm biến và chip lệnh của Kai."},"reaction_variants":{"wrong_branch":"Vẫn nhầm đường. Lần này nhìn kỹ tình huống drone đứng sát mép tầm quét… ở đó Kai đang trong tầm hay ngoài tầm?","IndentationError":"Vẫn dòng {line}. Python nhìn lề trái để biết dòng nào thuộc khối nào.","missing_var":"Lại không có lệnh ở tình huống {round}. Khi khối không chạy, {vars} lấy giá trị từ đâu?"},"counter_attack_banner":"CẢNH BÁO: OMNI ĐÃ ĐỔI DRONE, TẦM QUÉT ĐÃ KHÁC","outro":"Drone bay qua đầu Kai mà không quay đèn tìm kiếm. Trong bộ nhớ đệm của một trụ rào còn một tệp cũ, không thuộc dữ liệu tuần tra:","lore_fragment":"KTS-01: Tôi đặt tên cho mảnh này là Quyết định. Không có nó, công tắc biết cách tắt OMNI… nhưng không biết khi nào thì được tắt. Một công tắc như thế còn nguy hiểm hơn không có gì.","component":"Lệnh nấp","outro_beats":[{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Bạn đi chậm quá. Lịch của tôi nhanh hơn bạn nhiều.\""},{"kind":"echo","text":"Phía trước là Bãi Container. Đèn pha ở đó quét qua lại cả hai phía… đừng đứng yên một chỗ lâu quá."},{"kind":"kai","text":"Tôi sẽ đi tiếp. Theo LUẬT của tôi."}],"knowledge_summary":{"title":"Câu lệnh `if` và khối lệnh","sections":[{"heading":"Điều kiện đúng thì khối chạy","body":"`if điều_kiện:` kiểm một điều kiện. Dòng `if` kết thúc bằng dấu `:`. Các dòng lùi vào 4 dấu cách ngay bên dưới là khối lệnh của nó. Điều kiện là `True` thì khối chạy. Dòng không lùi vào nằm ngoài khối."},{"heading":"Điều kiện sai thì khối bị bỏ qua","body":"Điều kiện là `False` thì Python bỏ qua cả khối và đi tiếp xuống dòng sau khối. Ở ví dụ này, `Sot` không được in ra."},{"heading":"Khối có thể nhiều dòng","body":"Mọi dòng lùi vào cùng một mức ngay dưới `if` đều thuộc khối. Chúng cùng chạy, hoặc cùng bị bỏ qua. Khối kết thúc ở dòng đầu tiên không lùi vào nữa."},{"heading":"Giá trị mặc định rồi gán đè","body":"Gán cho biến một giá trị mặc định trước `if`. Trong khối, gán đè giá trị khác khi điều kiện đúng. Điều kiện sai thì biến giữ giá trị mặc định. Thứ tự hai lệnh gán quyết định kết quả: lệnh gán chạy sau cùng sẽ thắng."},{"heading":"Điều kiện là một phép so sánh","body":"Điều kiện thường là một trong sáu phép so sánh của bài trước: `==`, `!=`, `<`, `<=`, `>`, `>=`. Cẩn thận ở điểm bằng nhau: với `tuoi = 18`, `tuoi >= 18` là `True` nhưng `tuoi > 18` là `False`."}],"mistakes":[{"code":"x = 7\nif x > 5:\nprint(\"Lon\")","explain":"Dòng `print` không lùi vào, nên Python không thấy khối nào sau `if`. Lùi dòng đó vào 4 dấu cách."},{"code":"x = 7\nif x > 5\n    print(\"Lon\")","explain":"Dòng `if` thiếu dấu `:` ở cuối."},{"code":"x = 7\nif x = 5:\n    print(\"Nam\")","explain":"`=` là phép gán, không dùng được trong điều kiện. Muốn so sánh bằng nhau thì viết `==`."},{"code":"diem = 4\nif diem >= 5:\n    kq = \"DAT\"\nprint(kq)","explain":"Điều kiện sai nên khối không chạy, và `kq` chưa từng được gán. Gán giá trị mặc định cho `kq` trước `if`."},{"code":"diem = 7\nif diem >= 5:\n    kq = \"DAT\"\nkq = \"TRUOT\"\nprint(kq)","explain":"Lệnh gán mặc định nằm sau khối, nên nó luôn chạy sau cùng và ghi đè kết quả của khối. Đặt nó lên trước `if`."}],"next":"Khi chỉ có hai ngả, phần \"còn lại\" của một điều kiện có từ khóa riêng: `else`. Màn sau dùng nó."}}', revision = 2, updated_at = '2026-11-06T00:00:00.000Z', updated_by = 'migration' WHERE doc_id = 'level:2.2' AND revision = 1 AND updated_by = 'migration';
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.2' AND revision = 2 AND updated_at = '2026-11-06T00:00:00.000Z' AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;

-- level:2.3
UPDATE content_text SET text = '{"location":"Vành Sentinel · Bãi Container","briefing":"[NHẬT KÝ ĐIỀU KHIỂN – ĐÈN PHA BÃI CONTAINER]\nĐèn pha báo góc của nó theo độ, đo từ mép trái bãi Container. Mỗi lần đèn dừng là một tình huống.\nGóc dưới 90 là lúc đèn chiếu nửa trái của bãi, nên Kai phải đi sang phải. Từ 90 trở lên, kể cả đúng 90 khi đèn chiếu thẳng xuống lối giữa, là lúc đèn chiếu nửa phải, nên Kai cần sang trái.\nỞ mỗi tình huống, bộ điều khiển ghi góc đèn vào nhật ký, bất kể Kai chạy về hướng nào.","task_steps":["Bấm CHẠY với mã có sẵn. Sau mỗi lượt, những dòng mờ trong editor là những dòng không chạy ở tình huống đang hiện.","Sửa để ở mọi tình huống, `huong` có đúng một hướng theo luật ở ô Mục tiêu, kể cả khi góc đèn đúng bằng mốc.","Dòng ghi góc đèn phải in ra ở mọi tình huống. Không in thêm dòng nào khác. Không sửa dòng khóa.","Hoàn thành khi cả 2 mục tiêu chuyển thành xanh ở cả ba tình huống. Dùng không quá 3 câu lệnh và vẫn đúng khi OMNI đổi góc quét thì được thêm sao."],"objectives":[{"var":"huong","label":"Hướng Kai chạy: SANG PHAI khi góc đèn dưới 90, còn lại SANG TRAI"},{"line":1,"label":"GOC DEN:, một dấu cách, rồi góc đèn"}],"hints":["Sau mỗi lượt, hãy nhìn các dòng mờ: đó là những dòng không chạy ở tình huống đang hiện. Dòng ghi góc đèn đang nằm trong khối nào? Và khi góc đúng bằng 90, còn dòng gán hướng nào sáng không?","Chỉ cần kiểm tra góc đèn một lần. Điều kiện đúng thì Kai đi một hướng, mọi trường hợp còn lại thì đi hướng kia, không cần viết điều kiện thứ hai. Dòng ghi góc đặt sau khối, sát lề trái.\n\nnếu  <góc dưới mốc>\n    hướng = <một hướng>\ncòn lại\n    hướng = <hướng kia>\nin   GOC DEN: <góc>","Mảnh tài liệu Python còn đọc được:\nif diem >= 5:\n    ket_qua = \"DAT\"\nelse:                    → else không có điều kiện, nhận mọi trường hợp còn lại\n    ket_qua = \"CHUA DAT\"\nprint(ket_qua)           → sát lề trái, sau khối: luôn chạy\nDòng thụt lề thuộc khối ngay trên nó và chỉ chạy khi khối đó chạy.\nGán biến ở cả hai nhánh thì sau khối biến luôn có giá trị."],"reactions":{"entry":"Bãi Container. Đèn pha trên tháp quét qua quét lại, mỗi lần dừng là một tình huống. Kai chỉ có hai ngả. Chưa cần sửa gì… bạn chạy một lần rồi nhìn những dòng mờ trong editor.","output_missing":"Ở tình huống {round}, nhật ký góc đèn trống từ dòng {out_line}. Dòng ghi góc chỉ chạy khi khối lệnh chứa nó chạy.","missing_var":"Ở tình huống {round}, không nhánh nào gán {vars}. Kai không có hướng nào để chạy… anh đứng yên giữa lối, ngay dưới đèn.","wrong_branch":"Thứ mã đưa ra là của một tình huống khác. Mã vẫn đi qua một nhánh có thật… chỉ là không đúng với lần đèn dừng này. Nhìn xem ở tình huống trượt, dòng nào còn sáng.","wrong_value":"Ở tình huống {round}, {vars} giữ một hướng không có trong luật. Soát từng chữ với ô Mục tiêu.","type_mismatch":"Ở tình huống {round}, {vars} sai kiểu dữ liệu. Bộ điều khiển chỉ đọc hướng viết bằng chữ.","type_mismatch_value_match":"Ở tình huống {round}, {vars} trông đúng… nhưng sai kiểu dữ liệu. Bộ điều khiển vẫn không đọc được.","output_mismatch":"Ở tình huống {round}, dòng nhật ký thứ {out_line} lệch từ ký tự thứ {col}. Bộ điều khiển không đoán ý… nó ghi đúng những gì nhận được.","output_case_only":"Ở tình huống {round}, dòng nhật ký thứ {out_line} chỉ sai cỡ chữ. Bộ điều khiển phân biệt chữ hoa với chữ thường.","output_extra":"Ở tình huống {round}, nhật ký có thêm {count} dòng mà bộ điều khiển không hỏi. Nó chỉ cần dòng góc đèn.","output_is_label":"Ở tình huống {round}, dòng nhật ký thứ {out_line} ghi nguyên tên một ô nhớ, cả cặp ngoặc nhọn. Bộ điều khiển cần giá trị trong ô đó… không cần cái tên.","SyntaxError":"Dòng {line}. Trình dịch không đọc nổi câu này. Mã chưa chạy… đèn chưa dừng lần nào. Đọc kỹ dòng báo lỗi Python in ra.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng quyết định dòng nào thuộc khối nào.","TypeError":"Dòng {line}. TypeError. Hai giá trị khác kiểu vừa bị ghép vào cùng một phép tính.","ValueError":"Dòng {line}. ValueError. Một giá trị không đổi được sang thứ mã đòi.","NameError":"Dòng {line}. NameError. Mã dùng một cái tên mà chưa nhánh nào gán… hoặc tên đó bị gõ sai.","ZeroDivisionError":"Dòng {line}. Chia cho không. Lõi từ chối.","AttributeError":"Dòng {line}. AttributeError. Giá trị này không có thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Mã dừng giữa chừng ở tình huống {round}. Những dòng sau nó chưa kịp chạy.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi drone lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ngoài Vành Sentinel, ta chỉ có những gì đang cầm trong tay.","input_unsupported":"Không có ai ở đầu kia để trả lời. Góc đèn đã nằm sẵn ở dòng khóa.","system_exit":"Mã tự dừng giữa chừng. Bộ điều khiển không nhận được phần còn lại.","alert_exceeded":"Kai qua được cả ba tình huống. Nhưng mã dùng {count} câu lệnh… Mỗi lần kiểm thêm góc đèn hay đổi hướng giữa chừng là một lần drone có thể nghe thấy.","counter_ValueError":"OMNI đổi nhịp quét. Dòng {line} lỗi: ValueError. Mã không chịu được những góc mới.","counter_error":"OMNI đổi nhịp quét. Dòng {line}: {error_type}. Mã không chạy nổi với những góc mới.","counter_type_mismatch":"OMNI đổi nhịp quét. Với những góc mới, {vars} ra sai kiểu dữ liệu. Bộ điều khiển không đọc được.","wrong_value_counter":"OMNI đổi nhịp quét. Mã của bạn vẫn theo nhịp cũ… đèn dừng ở chỗ mới, và Kai chạy thẳng vào vùng sáng.","counter_timeout":"OMNI đổi nhịp quét. Mã của bạn treo ở những góc mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Kai qua được bãi. Drone không ghi nhận gì.","three_stars":"Đèn đổi nhịp quét… Kai vẫn luôn ở phía tối. Tôi ghi nhận điều đó.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại từng tình huống trong terminal."},"reaction_variants":{"wrong_branch":"Vẫn là thứ của một tình huống khác. Ở tình huống trượt, dòng nào mờ, dòng nào còn sáng?","missing_var":"Ở tình huống {round}, Kai vẫn không có hướng. Nhìn các dòng gán hướng ở tình huống đó… dòng nào còn sáng?","alert_exceeded":"Vẫn {count} câu lệnh. Đếm xem ở mỗi tình huống, mã kiểm góc đèn mấy lần và gán hướng mấy lần."},"counter_attack_banner":"CẢNH BÁO: OMNI ĐỔI NHỊP QUÉT CỦA ĐÈN PHA","outro":"Kai ra tới cuối bãi. Đèn pha vẫn đang quét, và mỗi lần dừng, nó chiếu đúng vào chỗ Kai vừa rời đi. Trong hộp điều khiển đèn còn lưu một bản ghi kiểm thử cũ:","lore_fragment":"KTS-07: Tôi đã cho nó chạy qua mọi nhánh, từng nhánh một. Mỗi nhánh một lý do nhưng tôi chỉ ghi lại các nhánh rẽ về đâu, không ghi vì sao. Có những lý do không nên nằm trong nhật ký.","component":"Ngả rẽ","outro_beats":[{"kind":"log","text":"Trên vách một container có ký hiệu trạm R-17 của Mạng Mù, khắc bằng tay. Đã có người qua đây trước Kai."},{"kind":"echo","text":"Vết khắc đã gỉ sét. Nó đã có từ lâu rồi… ngoài chuyện đó, tôi không kiểm tra được gì."},{"kind":"kai","text":"Người khắc dấu này có tới được phía bên kia không?"}],"knowledge_summary":{"title":"`else` và dòng sau khối lệnh","sections":[{"heading":"`if` / `else`: đúng một nhánh chạy","body":"`if` kiểm một điều kiện. Điều kiện đúng thì khối thụt lề dưới `if` chạy, sai thì khối dưới `else` chạy. Mỗi lần chạy, đúng một trong hai khối chạy: không bao giờ cả hai, cũng không bao giờ không khối nào."},{"heading":"`else` không có điều kiện","body":"`else` nhận mọi trường hợp mà `if` không nhận, kể cả giá trị nằm đúng trên mốc. Sau `else` chỉ viết dấu hai chấm, không viết điều kiện. Ở ví dụ, `diem` bằng đúng 5 nên `diem < 5` sai và khối `else` chạy."},{"heading":"Dòng sau khối luôn chạy","body":"Dòng viết sát lề trái sau khối `if`/`else` không thuộc nhánh nào. Nó chạy sau khi một nhánh đã chạy xong, dù đó là nhánh nào."},{"heading":"Thụt lề quyết định khối","body":"Ở đây dòng `print(\"DA CHAM XONG\")` thụt lề bằng thân `else`, nên nó thuộc khối `else`. Điểm 8 đi vào nhánh `if`, nên dòng đó không chạy. So với ví dụ trước, hai dòng này chỉ khác khoảng trắng đầu dòng."},{"heading":"Hai `if` rời so với `if` / `else`","body":"Hai `if` rời là hai lần kiểm riêng. Viết lệch ở giá trị bằng mốc thì có giá trị không lọt vào `if` nào (như 5 ở đây), hoặc lọt vào cả hai. `if`/`else` chỉ kiểm một lần và không bao giờ để hở. Lần kiểm thứ hai cũng tốn thêm một câu lệnh."},{"heading":"Gán ở cả hai nhánh","body":"Gán `ket_qua` trong cả hai nhánh thì sau khối biến luôn có giá trị, dù nhánh nào chạy. Một dòng `print` sau khối là đủ để in nó."}],"mistakes":[{"code":"diem = 7\nif diem >= 5:\n    print(\"DAT\")\nelse diem < 5:\n    print(\"CHUA DAT\")","explain":"`else` không nhận điều kiện. Python đọc tới `diem` sau `else` thì báo thiếu dấu hai chấm. Viết `else:` và để `else` tự nhận mọi trường hợp còn lại."},{"code":"diem = 7\nif diem >= 5:\n    print(\"DAT\")\nelse:\nprint(\"CHUA DAT\")","explain":"Thân `else` phải thụt lề vào trong, như thân `if`. Dòng `print` nằm sát lề trái nên Python thấy `else:` không có khối nào."},{"code":"diem = 5\nif diem < 5:\n    ket_qua = \"CHUA DAT\"\nif diem > 5:\n    ket_qua = \"DAT\"\nprint(ket_qua)","explain":"Với `diem` bằng 5, không điều kiện nào đúng, nên không dòng nào gán `ket_qua`. Dòng `print` dùng một tên chưa có. Dùng `if`/`else` để luôn có một nhánh chạy."},{"code":"diem = 8\nif diem >= 5:\n    ket_qua = \"DAT\"\nelse:\n    ket_qua = \"CHUA DAT\"\n    print(ket_qua)","explain":"Dòng `print` thụt lề nên nằm trong khối `else` và chỉ chạy khi điểm chưa đạt. Điểm 8 đi vào nhánh `if`, chương trình chạy xong mà không in gì. Đưa dòng `print` ra sát lề trái, sau khối."}],"next":"Màn sau có nhiều hơn hai ngả. Bạn sẽ xét lần lượt từng mức: mức nào đúng trước thì nhánh đó chạy."}}', revision = 2, updated_at = '2026-11-06T00:00:00.000Z', updated_by = 'migration' WHERE doc_id = 'level:2.3' AND revision = 1 AND updated_by = 'migration';
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.3' AND revision = 2 AND updated_at = '2026-11-06T00:00:00.000Z' AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;

-- level:2.4
UPDATE content_text SET text = '{"location":"Vành Sentinel · Tháp Đèn Pha","briefing":"[NHẬT KÝ HỆ THỐNG – THÁP ĐÈN PHA]\nTháp Đèn Pha đặt mức báo động cho cả khu. Tháp đo khoảng cách, tính bằng mét, tới tín hiệu lạ gần nhất, rồi chọn một trong bốn mức. Mức càng cao, đèn pha quét càng dày và drone kéo về càng đông.\nTháp xét từ gần nhất ra xa và dừng ở mức đầu tiên khớp được. Thang bốn mức nằm ở ô Mục tiêu.\nMỗi lần đo là một tình huống. Kai phải in ra đúng mức tháp sẽ đặt, đúng từng ký tự… trước khi đèn kịp quay về phía anh.","task_steps":["Bấm CHẠY với mã có sẵn. Sau mỗi lượt chạy, dòng nào mờ đi là dòng không chạy ở tình huống đang hiện.","Sửa mã để mỗi tình huống in đúng một dòng: mức tháp sẽ đặt, theo thang ở ô Mục tiêu.","Để ý khoảng cách đúng bằng một mốc thì thuộc mức nào, vì thang ghi \"dưới\". Không sửa dòng khóa.","Hoàn thành khi mục tiêu chuyển thành xanh ở cả bốn tình huống. Dùng không quá 5 câu lệnh và vẫn đúng khi OMNI đổi khoảng cách thì được thêm sao."],"objectives":[{"line":1,"label":"MUC:, một dấu cách, rồi mức báo động: dưới 20 mét là BAO DONG, dưới 50 mét là NGUY HIEM, dưới 100 mét là CANH GIAC, từ 100 mét trở lên là AN TOAN"}],"hints":["Nhìn tình huống 1: tín hiệu ở rất gần, vậy mà tháp chọn một mức nhẹ. Sau lượt chạy, dòng nào còn sáng? Python xét các điều kiện từ trên xuống và dừng ở điều kiện đúng đầu tiên. Với một khoảng cách rất nhỏ, điều kiện nào đúng trước?","Xếp các mức từ hẹp nhất (gần nhất) tới rộng nhất. Mức cuối nhận mọi khoảng cách còn lại nên không cần điều kiện. \"Dưới 50\" nghĩa là đúng 50 mét thì chưa thuộc mức đó.\n\nnếu khoảng cách dưới 20      → in mức gần nhất\nnếu không, mà dưới 50        → in mức kế tiếp\nnếu không, mà dưới 100       → in mức kế tiếp\ncòn lại                      → in mức xa nhất","Mảnh tài liệu Python còn đọc được:\ndiem = 7\nif diem >= 9:\n    print(\"Gioi\")\nelif diem >= 7:       → chỉ nhánh đúng đầu tiên chạy, in Kha\n    print(\"Kha\")\nelse:                 → nhận mọi giá trị còn lại\n    print(\"Dat\")\n\nĐặt điều kiện rộng (diem >= 5) lên đầu thì các nhánh hẹp phía sau không bao giờ tới lượt.\ndiem < 5 và diem <= 5 chỉ khác nhau khi diem đúng bằng 5.\nCác if rời đều được kiểm tra: một giá trị có thể chạy nhiều nhánh và in nhiều dòng."],"reactions":{"entry":"Tháp Đèn Pha đặt mức báo động cho cả khu. Bạn cần biết trước tháp sẽ chọn mức nào… trước khi đèn quay về phía mình. Chạy một lần, rồi xem dòng nào còn sáng.","wrong_branch":"Mức bạn in ra là mức của một tình huống khác. Tháp có dừng ở một nhánh thật… chỉ là dừng quá sớm hoặc quá muộn. Xem những dòng còn sáng.","output_extra":"Ở tình huống {round}, mã in thêm {count} dòng. Tháp chỉ đặt một mức mỗi lần đo… vậy mà nhiều nhánh đã cùng chạy.","output_missing":"Ở tình huống {round}, bạn không đưa ra mức nào. Dòng in không chạy tới.","output_mismatch":"Tình huống {round}: dòng in lệch từ ký tự thứ {col}. Tháp không đoán ý… nó đọc từng ký tự.","output_case_only":"Tình huống {round}: từ ký tự thứ {col}, chữ thì đúng nhưng sai cỡ chữ. Tháp không bỏ qua cỡ chữ.","NameError":"Dòng {line}. NameError ở tình huống {round}. Tên bạn in ra chưa hề có giá trị… không nhánh nào nhận khoảng cách đó.","alert_exceeded":"Đúng cả bốn tình huống. Nhưng {count} câu lệnh… tháp chỉ xét mỗi mức một lần, còn mã của bạn xét lại hoặc gán đè. Sentinel đã ghi nhận.","wrong_value_counter":"OMNI cho tín hiệu dừng ở chỗ mới. Mức bạn in ra không khớp mức nào trong thang.","counter_error":"OMNI đổi khoảng cách. Dòng {line}: {error_type}. Mã không trụ nổi.","counter_timeout":"OMNI đổi khoảng cách. Mã của bạn treo ở tình huống mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","SyntaxError":"Dòng {line}. Trình dịch không đọc nổi câu này. Chương trình chưa chạy… tháp chưa nhận được gì.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng… là ngữ pháp.","TypeError":"Dòng {line}. TypeError ở tình huống {round}. Hai giá trị khác kiểu vừa bị ghép vào một phép tính.","runtime_error":"Dòng {line}. {error_type} ở tình huống {round}. Chương trình dừng giữa chừng… tháp không nhận được mức nào.","two_stars":"Tháp hạ mức đúng lúc. Không để lại dấu vết.","three_stars":"Tín hiệu dừng đúng trên vạch… mà bạn vẫn đoán trúng. Tôi ghi nhận điều đó.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi đèn pha quay tới.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở Vành Sentinel, ta chỉ có những gì đang cầm trong tay.","system_exit":"Chương trình tự dừng giữa chừng. Tháp không nhận được mức nào.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại dòng tháp nhận được ở từng tình huống trong terminal."},"reaction_variants":{"wrong_branch":"Vẫn là mức của một tình huống khác. Nhìn dòng đầu tiên còn sáng: tháp đã dừng ở đó.","output_extra":"Vẫn thừa {count} dòng. Đếm số dòng in ra ở một tình huống… tháp chỉ cần một.","alert_exceeded":"Vẫn {count} câu lệnh. Đếm xem một khoảng cách bị so bao nhiêu lần trước khi mã in ra mức."},"counter_attack_banner":"CẢNH BÁO: OMNI CHO TÍN HIỆU DỪNG ĐÚNG TRÊN CÁC VẠCH CỦA THANG","outro":"Tháp hạ về mức thấp nhất đúng lúc Kai đi qua chân tháp. Trên màn hình bảo trì, bảng luật của tháp vẫn mở. Ở góc bảng có một dòng chú thích của người đặt ngưỡng:","lore_fragment":"KTS-02: Các ngưỡng do tám người chúng tôi đặt. Con số 60 được chọn trong một buổi chiều. Từ đó tới giờ, không ai nghĩ lại về nó.","component":"Thang báo động","outro_beats":[{"kind":"log","text":"Bảng luật của tháp còn một thang thứ hai. Thang này đo công dân.\nMỨC TUÂN THỦ DƯỚI 60% → TÁI ĐỊNH HƯỚNG"},{"kind":"kai","text":"Ba tuần trước, Nhi bị tái định hướng. Tất cả chỉ cần đúng một phép so sánh."},{"kind":"echo","text":"Ngưỡng này áp cho mọi công dân. Tháp chỉ so mức tuân thủ với con số đó, rồi chọn… Tháp không cần biết người đó là ai."}],"knowledge_summary":{"title":"Chuỗi if / elif / else: chọn một trong nhiều nhánh","sections":[{"heading":"Chuỗi `if / elif / else`","body":"Một chuỗi bắt đầu bằng `if`, tiếp theo là một hay nhiều `elif` (viết tắt của \"else if\"), và có thể kết bằng `else`. Python xét các điều kiện từ trên xuống. Gặp điều kiện đúng đầu tiên thì Python chạy nhánh đó rồi bỏ qua mọi nhánh còn lại. Mỗi lần chạy, chuỗi chỉ chạy đúng một nhánh."},{"heading":"Nhánh đúng đầu tiên thắng","body":"Thứ tự các nhánh quyết định kết quả. Ở ví dụ này, `diem >= 5` đứng đầu và đúng với 9, nên Python dừng ngay ở đó. Hai nhánh phía sau không bao giờ tới lượt, dù điều kiện của chúng cũng đúng. Khi các khoảng chồng lên nhau, đặt điều kiện hẹp nhất lên trước."},{"heading":"`else` ở cuối chuỗi","body":"`else` không có điều kiện. Nó nhận mọi giá trị mà các nhánh phía trên không nhận. Thiếu `else` thì có những giá trị đi qua cả chuỗi mà không chạy nhánh nào."},{"heading":"Các `if` rời không phải một chuỗi","body":"Mỗi `if` mở một chuỗi mới, nên Python kiểm tra từng `if` một. Với `diem = 9`, cả hai điều kiện đều đúng và chương trình in hai dòng. Muốn chỉ một nhánh chạy, nối chúng bằng `elif`. Cũng có thể viết mỗi `if` cho đúng một khoảng (cần cả mốc dưới lẫn mốc trên, ở màn sau), nhưng chuỗi `elif` gọn hơn: nhờ thứ tự, mỗi nhánh chỉ cần một mốc."},{"heading":"`<` hay `<=` ở mốc","body":"`<` và `<=` chỉ khác nhau khi giá trị đúng bằng mốc. Với `diem = 5`, `diem < 5` sai còn `diem <= 5` đúng, nên hai đoạn mã cho hai kết quả khác nhau. Đọc kỹ luật: \"dưới 5\" là `< 5`, \"từ 5 trở xuống\" là `<= 5`."},{"heading":"Gán trong nhánh rồi in một lần","body":"Mỗi nhánh có thể gán một giá trị cho cùng một biến, rồi chương trình in biến đó một lần sau chuỗi. Kết quả giống như đặt `print` trong từng nhánh. Cách này cần `else`, để biến luôn có giá trị dù rơi vào nhánh nào."}],"mistakes":[{"code":"diem = 9\nif diem >= 5:\n    print(\"Dat\")\nelse:\n    print(\"Chua dat\")\nelif diem >= 9:\n    print(\"Gioi\")","explain":"`else` phải là nhánh cuối của chuỗi. Một `elif` đặt sau `else` không thuộc chuỗi nào, nên Python báo lỗi cú pháp ngay khi đọc mã (Python 3.13 chỉ ghi `invalid syntax`). Chuyển `elif` lên trước `else`."},{"code":"diem = 6\nif diem >= 9:\n    print(\"Gioi\")\nelif diem >= 5:\nprint(\"Dat\")","explain":"Thân của `elif` phải lùi vào so với dòng `elif`. Ở đây `print` nằm sát lề trái, nên Python không tìm thấy thân của nhánh."},{"code":"diem = 2\nif diem >= 9:\n    loai = \"Gioi\"\nelif diem >= 5:\n    loai = \"Dat\"\nprint(loai)","explain":"Với `diem = 2`, không điều kiện nào đúng, nên chưa dòng nào gán giá trị cho `loai`. Thêm `else` để giá trị nào cũng gán `loai`."},{"code":"diem = 8\nif diem >= 7:\n    print(\"Kha\")\nif diem >= 5:\n    print(\"Dat\")","explain":"Hai `if` rời được kiểm tra riêng. `diem = 8` thỏa cả hai điều kiện nên chương trình in hai dòng. Đổi `if` thứ hai thành `elif` thì chỉ còn `Kha`."}],"next":"Màn sau: một quyết định ghép từ nhiều điều kiện cùng lúc."}}', revision = 2, updated_at = '2026-11-06T00:00:00.000Z', updated_by = 'migration' WHERE doc_id = 'level:2.4' AND revision = 1 AND updated_by = 'migration';
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.4' AND revision = 2 AND updated_at = '2026-11-06T00:00:00.000Z' AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;

-- level:2.5
UPDATE content_text SET text = '{"location":"Vành Sentinel · Ngã Tư Tuần Tra","briefing":"[NHẬT KÝ CỦA KAI – NGÃ TƯ TUẦN TRA]\nĐây là chỗ hai lộ trình drone cắt nhau. Một drone đứng gác ngay giữa ngã tư. Đèn pha trên tháp thỉnh thoảng quét ngang mặt đường.\nCó ba thứ quyết định tôi qua được hay không: drone cách tôi bao xa, camera của nó đang bật hay tắt, và đèn pha có đang chiếu không.\nTôi chỉ qua được khi drone ở xa hoặc camera tắt, và đèn pha không chiếu.\nChỉ cần sai một điều kiện là drone sẽ phát hiện ra tôi.","task_steps":["Ba dòng khóa là dữ liệu cảm biến của tình huống đang xét. Mỗi tình huống, game nạp dữ liệu mới vào đó, nên bạn không sửa ba dòng này.","Sửa điều kiện sau `if` cho đúng luật ở ô Mục tiêu. Đọc kỹ xem chữ \"và\" trong luật áp lên phần nào.","Sau mỗi lượt chạy, xem tình huống nào bị phát hiện và dòng nào bị làm mờ. Dòng mờ là dòng không chạy ở tình huống đó.","Bấm CHẠY. Hoàn thành khi qua cả bốn tình huống. Dùng không quá 3 câu lệnh và qua được lượt OMNI đổi luật tuần tra thì được thêm sao."],"objectives":[{"line":1,"label":"Lệnh cho Kai: in LENH: QUA khi drone ở xa hơn 40 mét hoặc camera tắt, và đèn pha không chiếu. Các trường hợp còn lại in LENH: CHO."}],"hints":["Nhìn tình huống bị phát hiện và dòng bị làm mờ. Đọc to luật lên, rồi tự hỏi: khi drone ở xa, điều kiện hiện tại còn xét tới đèn pha không?\nRồi nhìn lại dòng 7: \"camera tắt\" đang được viết thế nào?","Luật có hai phần, nối với nhau bằng chữ \"và\":\n  phần 1: drone ở xa HOẶC camera tắt\n  phần 2: đèn pha không chiếu\nPhần 1 tự nó đã là một lựa chọn \"hoặc\". Python tính \"và\" trước \"hoặc\", nên bạn phải gói phần 1 lại thành một khối rồi mới nối với phần 2:\n  nếu [phần 1] và [phần 2] thì qua, ngược lại thì chờ.","Mảnh tài liệu Python còn đọc được:\nTrue and False              → False\nTrue or False               → True\nnot True                    → False\nTrue or False and False     → True    (and tính trước or)\n(True or False) and False   → False   (trong ngoặc tính trước)\nmua = False\nnot mua                     → True\nMỗi vế của and, or là một giá trị đúng/sai. Muốn nhóm khác thứ tự mặc định thì đặt ngoặc."],"reactions":{"entry":"Ngã Tư Tuần Tra. Một drone gác giữa đường, đèn pha trên tháp quét qua theo nhịp. Luật qua đường có ba phần… Chạy một lần, rồi xem tình huống nào bị phát hiện.","wrong_branch":"Mã đã ra quyết định của một tình huống khác. Luật đúng một phần… nhưng có một phần của điều kiện đang bị xét sai chỗ, hoặc bị lật ngược. Nhìn dòng bị làm mờ.","output_mismatch":"Tình huống {round}, dòng {out_line}. Lệch từ ký tự thứ {col}. Kai không hiểu lệnh này.","output_case_only":"Tình huống {round}, dòng {out_line}. Đúng chữ… sai cỡ chữ. Kai chỉ nhận lệnh viết đúng từng ký tự.","output_missing":"Tình huống {round}. Kai đứng chờ ở mép ngã tư… nhưng không nhận được lệnh nào.","output_extra":"Tình huống {round}. Kai nhận đủ lệnh, rồi còn thêm một dòng ngoài giao thức. Drone nghe thấy dòng thừa đó.","SyntaxError":"Dòng {line}. Trình dịch không đọc được luật này. Chưa tình huống nào chạy.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng… là ngữ pháp.","NameError":"Tình huống {round}. Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có. Soát từng ký tự.","TypeError":"Tình huống {round}. Dòng {line}. TypeError. Dòng này ghép hai giá trị khác kiểu vào cùng một phép toán.","ValueError":"Tình huống {round}. Dòng {line}. ValueError. Giá trị này không đổi được sang kiểu đó.","AttributeError":"Tình huống {round}. Dòng {line}. AttributeError. Giá trị này không có thứ bạn đang gọi.","ZeroDivisionError":"Tình huống {round}. Dòng {line}. Chia cho không. Lõi từ chối.","runtime_error":"Tình huống {round}. Dòng {line}. {error_type}. Chương trình dừng giữa chừng, Kai không nhận được lệnh.","input_unsupported":"Ở ngã tư này không có kênh nhập. Kai chỉ có ba cảm biến… dữ liệu đã nằm sẵn trong đó.","alert_exceeded":"Đúng luật. Nhưng {count} câu lệnh… mỗi lần kiểm hay gán thêm là một lần drone có thể nghe thấy. Luật này gói gọn được trong một câu điều kiện.","wrong_value_counter":"OMNI đổi luật tuần tra. Với dữ liệu mới, lệnh in ra ở dòng {out_line} sai chữ.","counter_error":"OMNI dời chốt gác. Dòng {line}: {error_type}. Mã không chịu được dữ liệu mới.","counter_timeout":"OMNI đổi luật tuần tra. Mã của bạn treo trên dữ liệu mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Qua ngã tư. Drone không quay đầu.","three_stars":"OMNI dời chốt gác. Luật của Kai vẫn đúng.","generic":"Có gì đó không khớp. Đọc lại nhật ký dải tuần tra.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Mở mức gợi ý tiếp theo trong nhật ký.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi drone lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở ngã tư này, Kai chỉ có ba cảm biến.","system_exit":"Chương trình tự dừng giữa chừng. Kai không nhận được lệnh nào."},"reaction_variants":{"wrong_branch":"Vẫn là quyết định của một tình huống khác. Đặt tình huống bị phát hiện cạnh một tình huống đã qua… chúng khác nhau ở cảm biến nào?","alert_exceeded":"Vẫn {count} câu lệnh. Đếm xem drone có bao nhiêu lần để nghe thấy Kai… rồi gom các lần kiểm lại thành một."},"counter_attack_banner":"OMNI ĐỔI LUẬT TUẦN TRA · DRONE DỜI CHỐT GÁC","outro":"Kai lách qua ngã tư giữa hai lượt đèn. Drone vẫn đứng giữa đường, camera quay sang hướng khác.\nDưới chân cột đèn có một hộp điều khiển cũ, nắp đã gỉ. Bên trong vẫn lưu lịch tuần tra, kèm một dòng nhật ký:","lore_fragment":"KTS-03: Lịch tuần tra gốc do tám người chúng tôi viết. OMNI vẫn giữ nguyên như vậy. Cái gì đang chạy tốt thì cứ để yên đó.","component":"Điều kiện qua đường","outro_beats":[{"kind":"echo","text":"Tôi vừa so lịch vượt rào mà 0xA7 gửi lúc bạn mới tới Vành Sentinel với các luật bạn vừa giải. Hai bên khớp nhau tới từng giây."},{"kind":"echo","text":"…Lịch đó chỉ có trong hộp điều khiển gốc."},{"kind":"kai","text":"Tôi nhớ lời KTS-03 dặn ở Cổng phía Bắc: đừng tin tín hiệu nào mang mã 0xA7."},{"kind":"log","text":"Kai đi tiếp về phía Trạm Sạc Drone. Trên bức tường cạnh trạm, bảng lệnh của tháp đang sáng lên từng dòng."}],"knowledge_summary":{"title":"Điều kiện ghép: and, or, not","sections":[{"heading":"`and`: cả hai vế phải đúng","body":"`a and b` cho `True` khi cả `a` và `b` đều đúng. Chỉ cần một vế sai là kết quả thành `False`."},{"heading":"`or`: chỉ cần một vế đúng","body":"`a or b` cho `True` khi ít nhất một vế đúng. Kết quả chỉ là `False` khi cả hai vế đều sai."},{"heading":"`not` đảo một giá trị","body":"`not x` cho `True` khi `x` là `False`, và ngược lại. `not` chỉ áp lên giá trị đứng ngay sau nó."},{"heading":"Thứ tự tính và dấu ngoặc","body":"Python tính `not` trước, rồi tới `and`, sau cùng mới tới `or`. Vì vậy `True or False and False` được tính như `True or (False and False)`.\nMuốn nhóm theo cách khác thì đặt ngoặc: phần trong ngoặc được tính trước."},{"heading":"Điều kiện ghép trong `if`","body":"Một câu `if` với điều kiện ghép thay được cho nhiều câu `if` nối nhau. Mỗi vế phải là một phép so sánh đầy đủ, hoặc một giá trị đúng/sai."}],"mistakes":[{"code":"a = 5\nif a > 0 && a < 10:\n    print(a)","explain":"Python dùng chữ `and`, `or`, `not`. Các ký hiệu `&&`, `||`, `!` của ngôn ngữ khác là lỗi cú pháp."},{"code":"nong = True\nmua = False\nco_o = False\nprint(nong or mua and co_o)","explain":"Người viết muốn \"(nóng hoặc mưa) và có ô\". Không có ngoặc thì `and` được tính trước, nên Python hiểu thành \"nóng, hoặc (mưa và có ô)\". Viết `(nong or mua) and co_o`."},{"code":"x = 5\nif x == 1 or 2:\n    print(\"Dung\")","explain":"Vế sau `or` là `2`, không phải `x == 2`. Python coi số `2` là đúng, nên điều kiện luôn đúng. Mỗi vế phải là một phép so sánh đầy đủ: `x == 1 or x == 2`."}],"next":"Màn sau: một câu hỏi chỉ có nghĩa khi câu hỏi trước đã có câu trả lời. Bạn sẽ đặt một `if` bên trong một `if` khác, và xét một dòng trống đọc từ kênh nhập."}}', revision = 2, updated_at = '2026-11-06T00:00:00.000Z', updated_by = 'migration' WHERE doc_id = 'level:2.5' AND revision = 1 AND updated_by = 'migration';
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.5' AND revision = 2 AND updated_at = '2026-11-06T00:00:00.000Z' AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;

-- level:2.6
UPDATE content_text SET text = '{"location":"Vành Sentinel · Trạm Sạc Drone","briefing":"[NHẬT KÝ HỆ THỐNG – TRẠM SẠC DRONE]\nĐây là chỗ drone của Vành Sentinel quay về để sạc. Trên bảng lệnh của tháp, mỗi drone đang sạc có một ô lệnh và một mức pin.\nKai đọc bảng này qua kênh nhập, giống như ở Trạm Thẩm Vấn. Với mỗi drone, bảng lệnh sẽ gửi hai dòng: dòng đầu là mã lệnh, dòng sau là mức pin.\nÔ lệnh có thể trống, nghĩa là tháp chưa giao việc gì cho drone đó.\nKai phải xét theo thứ tự. Trước hết xem ô lệnh có gì không. Có lệnh thì chỉ còn hỏi đó là lệnh gì, pin không còn quan trọng. Ô lệnh trống thì mới nhìn tới pin. Luật cụ thể nằm ở ô Mục tiêu.","task_steps":["Bấm CHẠY với code có sẵn rồi đọc terminal. Mỗi lần gọi `input()` là đọc một dòng của bảng lệnh, và giá trị nhận về luôn là chuỗi, kể cả khi dòng đó trống.","Sửa code để chương trình xét đúng thứ tự ở ô Mục tiêu: hỏi ô lệnh có chữ hay không trước, rồi mới hỏi đó là lệnh gì hoặc mức pin bao nhiêu.","Chỉ in đúng một dòng bằng `print`. Lời nhắc viết trong `input()` cũng bị in ra, nên đừng thêm lời nhắc.","Hoàn thành khi qua cả bốn tình huống. Dùng không quá 6 câu lệnh và qua lượt OMNI đổi bảng lệnh thì được thêm sao."],"objectives":[{"line":1,"label":"Quyết định cho drone. Ô lệnh có chữ: in LENH: NAP nếu mã lệnh đúng là XUAT KICH, mã khác thì in LENH: CHO. Ô lệnh trống: in LENH: DI nếu pin dưới 30, còn lại in LENH: CHO"}],"hints":["Thứ đọc được từ kênh nhập luôn là chuỗi, kể cả mức pin. Muốn so pin với một con số thì phải đổi nó sang số trước.\nSau đó, nhìn tình huống bị phát hiện và các dòng bị làm mờ trong editor. Drone ở tình huống đó có lệnh không? Code của bạn có hỏi câu đó trước tiên không?","Chia quyết định thành hai tầng câu hỏi.\nTầng ngoài chỉ hỏi một câu: ô lệnh có chữ không?\nMỗi nhánh của tầng ngoài có câu hỏi riêng:\n  nếu ô lệnh có chữ:\n      nếu mã lệnh là lệnh xuất kích → NAP, còn lại → CHO\n  nếu ô lệnh trống:\n      nếu pin dưới ngưỡng → DI, còn lại → CHO\nMột dòng trống đọc từ kênh nhập là chuỗi rỗng, và Python coi chuỗi rỗng là sai khi đặt nó làm điều kiện.","Mảnh tài liệu Python còn đọc được:\nve = input()\ntuoi = int(input())\nif ve:\n    if ve == \"VIP\":\n        print(\"Ghe dau\")\n    else:\n        print(\"Ghe thuong\")\nelse:\n    if tuoi < 6:\n        print(\"Vao cung bo me\")\n    else:\n        print(\"Mua ve truoc\")\n\nKhối của `if` bên trong thụt thêm một mức. `else` thuộc về `if` nằm cùng mức thụt lề với nó.\n`if ve:` đúng khi chuỗi có ít nhất một ký tự, kể cả một dấu cách. Nó cho cùng kết quả với `if ve != \"\":`.\n`int(input())` đọc một dòng rồi đổi nó sang số nguyên."],"reactions":{"entry":"Trạm Sạc Drone. Với mỗi drone, bảng lệnh gửi hai dòng qua kênh nhập… Có lúc ô lệnh trống. Chạy thử một lần đã.","SyntaxError":"Dòng {line}. Python không đọc được câu này. Chưa drone nào nhận được quyết định.","IndentationError":"Dòng {line}. Khoảng trắng đầu dòng bị lệch. Với Python, khoảng trắng đó cũng là ngữ pháp.","TypeError":"Tình huống {round}, dòng {line}. Hai giá trị khác kiểu đang bị đem so với nhau. Mức pin đọc từ bảng trông giống như số… nhưng nó chưa phải là số.","ValueError":"Tình huống {round}, dòng {line}. Một dòng chữ đang bị bắt làm số. Bạn đọc hai dòng của bảng đúng thứ tự chưa?","NameError":"Tình huống {round}, dòng {line}. Dòng này gọi một tên biến chưa từng có. Soát lại từng ký tự.","AttributeError":"Tình huống {round}, dòng {line}. Giá trị này không có thứ bạn đang gọi.","runtime_error":"Tình huống {round}, dòng {line}. {error_type}. Chương trình dừng giữa chừng, drone chưa nhận được quyết định.","EOFError":"Tình huống {round}, dòng {line}. Code đang chờ một dòng mà bảng không gửi. Mỗi drone chỉ có hai dòng… đếm lại số lần bạn đọc kênh nhập.","output_has_prompt":"Tình huống {round}, dòng {out_line}. Lời nhắc của code cũng bị in ra, dính vào đầu dòng quyết định. Bảng lệnh không cần ai nhắc.","output_mismatch":"Tình huống {round}, dòng {out_line}. Lệch từ ký tự thứ {col}. Drone không hiểu quyết định đó.","output_case_only":"Tình huống {round}, dòng {out_line}. Đúng từng chữ, nhưng sai chữ hoa chữ thường. Drone không bỏ qua chỗ đó.","output_missing":"Tình huống {round}. Kai không nhận được quyết định nào cho drone này. Có một nhánh không in gì.","output_extra":"Tình huống {round}. Quyết định đã ra, rồi còn thêm dòng thừa. Mỗi drone chỉ nhận một dòng.","wrong_branch":"Code đã ra quyết định của một tình huống khác. Có một câu hỏi đang được hỏi khi nó chưa có nghĩa… Nhìn các dòng bị làm mờ.","timeout":"Code chạy quá lâu. Tôi cắt kết nối trước khi tháp ghi nhận.","resource_limit":"Tình huống {round}. Bộ nhớ quá tải. Tôi cắt tiến trình để laptop còn chạy được.","blocked_import":"Tình huống {round}. Mô-đun đó bị phong tỏa. Ở trạm này, bạn chỉ có những gì mang theo.","system_exit":"Tình huống {round}. Chương trình tự dừng giữa chừng. Drone không nhận được quyết định.","alert_exceeded":"Quyết định đúng, nhưng tốn {count} câu lệnh. Mỗi lần hỏi thêm hay gán thêm là một lần drone có thể nghe thấy… Có câu hỏi không cần hỏi lại ở mọi tình huống.","counter_ValueError":"OMNI gửi bảng lệnh mới. Dòng {line} không đổi được thứ bảng gửi sang số.","counter_error":"Bảng lệnh mới. Dòng {line}: {error_type}. Code không chịu được dữ liệu OMNI vừa gửi.","wrong_value_counter":"Bảng lệnh mới… lệnh in ra sai chữ. Drone vừa rời cột sạc.","counter_timeout":"Code treo khi đọc bảng lệnh mới. Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Bốn drone, không con nào rời cột. Nhưng OMNI vừa đổi bảng lệnh.","three_stars":"Bảng lệnh đổi, mà Kai vẫn đọc đúng. Không drone nào rời cột sạc.","repeated_fail":"Lần thứ {count}, vẫn cùng một lỗi. Mở mức gợi ý tiếp theo trong nhật ký.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc terminal theo từng tình huống."},"reaction_variants":{"wrong_branch":"Vẫn có drone nhận quyết định của tình huống khác. Đổi chỗ các câu hỏi chưa đủ… câu hỏi về pin chỉ có nghĩa khi ô lệnh trống.","TypeError":"Tình huống {round}, dòng {line}. Vẫn là chữ đem so với số. Mức pin cần thành số trước khi so.","alert_exceeded":"Vẫn {count} câu lệnh. Ô lệnh có chữ hay không, chỉ cần hỏi một lần."},"counter_attack_banner":"OMNI VIẾT LẠI BẢNG LỆNH CỦA TRẠM SẠC","outro":"Kai đọc hết bảng lệnh. Không có drone nào rời cột sạc, tất cả ở yên một chỗ.\nGiữa Vành Sentinel toàn ánh xanh lạnh, bảng lệnh là thứ hiếm hoi còn sáng màu vàng ấm. Cuối bảng còn một dòng ghi cũ, không thuộc lệnh tuần tra nào:","lore_fragment":"KTS-0█ · MÃ NGƯỜI VIẾT ĐÃ BỊ XÓA\nĐược ghi lại chín ngày sau buổi chia mảnh.\nĐã nộp. Bên nhận không hỏi gì thêm. Tôi chưa biết như thế là tốt hay xấu.","component":"Đọc bảng lệnh","outro_beats":[{"kind":"log","text":"BẢNG LỆNH CẬP NHẬT · MỌI CỘT SẠC\nLỆNH: XUẤT KÍCH\nĐÍCH: TÍN HIỆU KHÔNG ĐỊNH DANH · GẦN THÁP"},{"kind":"echo","text":"Lịch của tháp vừa đổi. Đợt quét lớn đã dời lên sớm hơn… Giờ quét mới gần hơn nhiều."},{"kind":"kai","text":"Tín hiệu không định danh gần tháp là tôi, và tôi phải lên tháp ngay bây giờ."},{"kind":"echo","text":"Luật cuối cùng đã vào bộ luật né. Từ đây, mỗi bước bạn đi phải qua cả sáu luật cùng một lúc… Tháp Sentinel ở ngay phía trước."}],"knowledge_summary":{"title":"Tổng kết: điều kiện lồng nhau và chuỗi rỗng","sections":[{"heading":"`if` trong `if`","body":"Có những câu hỏi chỉ có nghĩa khi đã biết câu trả lời cho câu hỏi trước. Khi đó, đặt `if` thứ hai vào trong khối của `if` thứ nhất và thụt thêm một mức. Khối bên trong chỉ chạy khi điều kiện bên ngoài đúng."},{"heading":"Chuỗi rỗng là sai","body":"Đặt một chuỗi vào chỗ điều kiện thì chuỗi rỗng `\"\"` là sai. Chuỗi có ít nhất một ký tự là đúng, kể cả chuỗi chỉ có một dấu cách."},{"heading":"`if chuoi:`","body":"Đọc `if ten:` là \"nếu có chữ\". Khi người dùng gõ Enter mà không nhập gì, `input()` trả về chuỗi rỗng `\"\"`, nên nhánh `else` chạy."},{"heading":"Viết rõ hơn: `!= \"\"`","body":"`if ten != \"\":` cho cùng kết quả với `if ten:`. Cách viết này dài hơn nhưng nói thẳng điều đang so sánh."},{"heading":"Lồng nhau và `and`","body":"Một `if` nằm trong một `if` khác, khi khối bên trong không có `else`, chạy giống một `if` ghép hai điều kiện bằng `and`. Ở ví dụ dưới, cả hai cách đều không in `Vao`, vì điều kiện về tuổi sai."}],"mistakes":[{"code":"diem = input()\nif diem < 50:\n    print(\"Thi lai\")","explain":"`input()` luôn trả về chuỗi, và Python không so chuỗi với số. Đổi sang số trước khi so: `diem = int(input())`."},{"code":"a = True\nb = False\nif a:\n    if b:\n        print(\"B\")\nelse:\n    print(\"Khong A\")","explain":"`else` thuộc về `if` nằm cùng mức thụt lề với nó. Ở đây `else` là của `if a:`, không phải của `if b:`, nên khi `a` đúng và `b` sai thì không dòng nào được in."},{"code":"ten = \" \"\nif ten:\n    print(\"Co ten\")","explain":"Một dấu cách vẫn là một ký tự, nên chuỗi `\" \"` không rỗng và điều kiện đúng."}],"next":"Màn sau là Boss. Trạm Sentinel sẽ chạy cả sáu luật qua ba pha tuần tra liên tiếp, và bộ luật né của bạn phải đúng ở mọi pha."}}', revision = 2, updated_at = '2026-11-06T00:00:00.000Z', updated_by = 'migration' WHERE doc_id = 'level:2.6' AND revision = 1 AND updated_by = 'migration';
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.6' AND revision = 2 AND updated_at = '2026-11-06T00:00:00.000Z' AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;

-- level:2.7
UPDATE content_text SET text = '{"location":"Vành Sentinel · Trạm Sentinel","briefing":"[NHẬT KÝ TRẠM SENTINEL]\nMột đợt quét lớn được dời lên sớm hơn thường lệ và đang bắt đầu quét. Trạm chạy bốn pha tuần tra liên tiếp. Ở mỗi pha, tháp nạp dữ liệu cảm biến mới về tầm quét, camera và đèn pha. Sau đó tháp gửi hai dòng qua kênh nhập: khoảng cách tới tín hiệu lạ và mã lệnh đang ghi trên bảng lệnh. Bảng lệnh có lúc để trống. Tín hiệu nào trả lời sai ở một pha sẽ bị khóa đèn, và cả lượt coi như hỏng.\nBộ luật né của Kai phát ra bốn dòng. Mỗi dòng ghép từ những luật Kai đã dựng ở sáu chặng trước. Luật của từng dòng nằm ở ô Mục tiêu.\nTín hiệu nào qua đủ bốn pha sẽ phải gặp luật khẩn cấp của tháp, với dữ liệu tháp chưa dùng lần nào.","task_steps":["Bản nháp của Kai có bốn khối, mỗi khối in một dòng. Bấm CHẠY trước, rồi đọc terminal để biết pha nào, dòng nào sai. Không sửa 3 dòng khóa.","Sửa từng khối cho khớp luật ở ô Mục tiêu. Sau mỗi lượt chạy, dòng mờ trong editor là dòng không chạy ở pha đang hiện. Mỗi pha tháp gửi dữ liệu khác, nên đừng chép tay thứ tháp gửi.","Lượt chỉ đạt khi qua đủ bốn pha liên tiếp.","Hoàn thành khi cả 4 mục tiêu chuyển thành xanh ở cả bốn pha. Dùng không quá 17 câu lệnh và qua được luật khẩn cấp thì bạn có thêm sao."],"objectives":[{"line":1,"label":"Luật 1 · Cảm biến tầm quét: TRONG TAM: rồi True khi khoảng cách không vượt tầm quét, ngược lại False (đúng như print in một giá trị bool)"},{"line":2,"label":"Luật 4 · Thang báo động: MUC: BAO DONG khi khoảng cách dưới 20, MUC: NGUY HIEM khi dưới 50, MUC: CANH GIAC khi dưới 100, còn lại MUC: AN TOAN"},{"line":3,"label":"Luật 6 · Đọc bảng lệnh: có mã lệnh thì in LENH DRONE: XUAT KICH khi mã đúng là XUAT KICH, mã khác thì LENH DRONE: CHO LENH; mã lệnh trống thì LENH DRONE: KHONG CO"},{"line":4,"label":"Luật 2, 3, 5 · Quyết định của Kai: KAI: NAP khi Kai trong tầm quét và drone thấy được Kai (camera bật hoặc đèn pha bật); nếu không, KAI: CHO khi đèn pha bật hoặc mã lệnh là XUAT KICH; còn lại KAI: QUA"}],"hints":["Mỗi khối là một luật Kai đã dựng ở một chặng trước. Khối nào sai cũng sai đúng như Kai từng sai ở chặng đó. Đọc terminal theo từng pha, sửa lỗi đầu tiên rồi chạy lại. Dòng mờ trong editor là dòng không chạy ở pha đang hiện.","Tự hỏi sáu câu, mỗi câu cho một chỗ trong bản nháp:\nKênh nhập: `input()` trả về kiểu gì? Đem kiểu đó so với một con số có được không?\nLuật 1: khoảng cách đúng bằng tầm quét thì Kai có ở trong tầm không?\nLuật 4: thang xét mức nào trước? Một khoảng cách rất gần có lọt vào mức xa hơn trước không?\nLuật 6: dòng in nằm trong khối nào? Nó có chạy cả khi bảng lệnh có mã không?\nQuyết định: khi luật nấp và luật chờ cùng đúng, luật nào phải thắng?\nQuyết định: trong một điều kiện có cả `and` lẫn `or`, phần nào được tính trước?","Mảnh tài liệu Python còn đọc được:\nprint(5 < 5, 5 <= 5)          → False True\nif diem >= 8: … elif diem >= 5: …   → chỉ nhánh đúng đầu tiên chạy\nif ghi_chu: …                 → \"\" là sai, \" \" là đúng\nTrue or False and False       → True (and tính trước or)\n(True or False) and False     → False\nint(\"7\") < 9                  → True\n\"7\" < 9                       → TypeError\nDòng không thụt lề viết sau một khối luôn chạy, dù nhánh nào được chọn."],"reactions":{"entry":"Trạm Sentinel. Đợt quét lớn đã tới… Tháp sẽ chạy bốn pha liên tiếp.","SyntaxError":"Dòng {line}. Python không đọc được câu lệnh này. Tháp chưa chạy pha nào.","IndentationError":"Dòng {line}. Lề trái lệch. Trong Python, khoảng trắng đầu dòng quyết định dòng nào thuộc khối nào.","TypeError":"Pha {round}, dòng {line}: TypeError. Tháp đem một thứ đọc từ kênh nhập ra so với một con số. Thứ đó đang mang kiểu gì?","ValueError":"Pha {round}, dòng {line}: ValueError. Một dòng từ kênh nhập không đổi được thành số. Bạn có đọc hai dòng theo đúng thứ tự tháp gửi không?","NameError":"Pha {round}, dòng {line}: NameError. Dòng này gọi một cái tên chưa từng có. Soát lại từng ký tự.","ZeroDivisionError":"Pha {round}, dòng {line}: chia cho không. Lõi Python từ chối.","AttributeError":"Pha {round}, dòng {line}: AttributeError. Giá trị này không có thứ bạn đang gọi.","runtime_error":"Pha {round}, dòng {line}: {error_type}. Mã dừng giữa chừng, các dòng sau chưa kịp phát.","EOFError":"Pha {round}, dòng {line}. Mỗi pha, kênh nhập chỉ có hai dòng. Mã của bạn đòi đọc thêm… kênh đã trống.","output_has_prompt":"Pha {round}, dòng {out_line}. Lời nhắc của bạn cũng đi ra, dính vào đầu dòng. Tháp không hỏi gì cả… tháp chỉ gửi dữ liệu.","wrong_branch":"Dòng {out_line} đã đi đúng một nhánh có thật… nhưng là nhánh dành cho một lúc khác. Nhìn các dòng mờ trong editor: đó là những dòng mã đã bỏ qua.","output_mismatch":"Pha {round}, dòng {out_line} lệch từ ký tự thứ {col}. Nếu một dòng phía trên không phát, các dòng sau sẽ dồn lên một bậc.","output_case_only":"Pha {round}, dòng {out_line}. Chữ thì đúng, nhưng sai hoa thường. Tháp không bỏ qua.","output_missing":"Pha {round}. Tháp đợi dòng {out_line} mà không thấy. Có một dòng in đã không chạy ở pha này.","output_extra":"Pha {round}. Tháp nhận nhiều hơn bốn dòng. Có hai nhánh cùng phát ra một lúc.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi tháp ghi nhận.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở trạm này, bạn chỉ có những gì mình mang theo.","system_exit":"Mã tự dừng giữa chừng. Tháp không nhận được phần còn lại.","alert_exceeded":"Bốn pha đều qua. Nhưng {count} câu lệnh là quá nhiều lần kiểm… Mỗi lần kiểm là một lần drone có thể nghe thấy.","counter_ValueError":"Luật khẩn cấp. Dòng {line} gặp một dòng kênh nhập không đổi được thành số: ValueError.","counter_error":"Tháp đổi luật. Dòng {line}: {error_type}. Mã không chịu được dữ liệu mới.","wrong_value_counter":"Luật khẩn cấp. Dữ liệu mới nằm đúng chỗ hai luật giáp nhau… dòng {out_line} vẫn chạy như với dữ liệu cũ.","counter_timeout":"Mã treo lúc tháp đổi luật. Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Bốn pha đều qua, không để lại dấu vết. Trên đỉnh tháp, luật khẩn cấp vẫn đang chờ.","three_stars":"Tháp đã đổi luật, nhưng bộ luật né vẫn đứng vững. Phía trên là lõi luật của tháp.","repeated_fail":"Lần thứ {count}, vẫn cùng một lỗi. Mở mức gợi ý tiếp theo trong nhật ký.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc terminal theo từng pha."},"reaction_variants":{"wrong_branch":"Dòng {out_line} vẫn chọn nhánh của một lúc khác. Đọc lại luật của dòng đó ở ô Mục tiêu, từng vế một.","output_mismatch":"Pha {round}, dòng {out_line} vẫn lệch, từ ký tự thứ {col}. Đặt dòng cần và dòng nhận cạnh nhau.","wrong_value_counter":"Luật khẩn cấp vẫn bắt được dòng {out_line}. Dữ liệu mới đứng đúng ở mép một luật… mã của bạn xếp nó sang phía nào?"},"counter_attack_banner":"LUẬT KHẨN CẤP · DỮ LIỆU MỚI NẰM ĐÚNG RANH GIỚI CÁC LUẬT","outro":"Đợt quét lớn đi qua chỗ Kai nấp. Đèn rọi qua mà không dừng lại.\nTừng chiếc drone lần lượt bay về trạm sạc. Kai vào chân tháp, rồi lên tới cửa lõi luật.\nKhông có ai trực. Tháp này chưa bao giờ cần tới con người.","lore_fragment":"KTS-02: Tôi giấu mảnh Quyết định trong một nhánh mà OMNI không bao giờ chọn. Điều kiện để vào nhánh đó là một quyết định do con người tự đưa ra. Bộ đếm của nhánh sẽ đứng ở số không cho tới khi có một người như thế đi qua đây.","outro_beats":[{"kind":"log","text":"Lõi luật mở bảng luật của tháp. Trong bảng có một nhánh chưa chạy lần nào kể từ ngày tháp được dựng, bộ đếm vẫn ghi 0.\nKai bước tới trước bảng. Nhánh đó mở ra."},{"kind":"card","text":"MẢNH THUẬT TOÁN 2/8 · QUYẾT ĐỊNH"},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Chúc mừng. Tôi biết bạn sẽ qua được tháp này. Tôi biết điều đó trước cả bạn.\""},{"kind":"echo","text":"Tín hiệu 0xA7 lần này phát ra từ chính tháp Sentinel. Tức là từ bên trong mạng của OMNI."},{"kind":"kai","text":"Tôi cất mảnh thứ hai vào túi áo, cạnh mảnh thứ nhất."}],"knowledge_summary":{"title":"Tổng kết Chương 2: so sánh và rẽ nhánh","sections":[{"heading":"So sánh cho ra `True` hoặc `False`","body":"Python có sáu phép so sánh: `==`, `!=`, `<`, `<=`, `>`, `>=`. Kết quả là một giá trị `bool`. Một dấu `=` là phép gán, hai dấu `==` mới là phép so sánh. Ở điểm bằng nhau, `<` cho `False` còn `<=` cho `True`."},{"heading":"`if` và khối lệnh","body":"Các dòng thụt lề dưới `if` tạo thành một khối. Khối chỉ chạy khi điều kiện đúng. Điều kiện sai thì Python bỏ qua cả khối."},{"heading":"`else` và dòng sau khối","body":"`else` nhận mọi trường hợp mà điều kiện của `if` không bắt. Dòng không thụt lề viết sau khối luôn chạy, dù nhánh nào được chọn."},{"heading":"`elif` và thứ tự nhánh","body":"Python xét các điều kiện từ trên xuống, và chỉ nhánh đúng đầu tiên chạy. Vì vậy điều kiện hẹp phải đứng trước điều kiện rộng. Nếu đặt `diem >= 5` lên đầu, điểm 9 cũng chỉ ra \"Dat\"."},{"heading":"`and`, `or`, `not`","body":"`and` đúng khi cả hai vế đúng, `or` đúng khi có ít nhất một vế đúng, `not` đảo giá trị. Trong cùng một điều kiện, Python tính `and` trước `or`. Muốn tính theo cách khác thì đặt ngoặc."},{"heading":"Điều kiện lồng; chuỗi rỗng","body":"Một `if` có thể nằm trong khối của một `if` khác. Khối bên trong chỉ được xét khi điều kiện bên ngoài đúng. Khi dùng một chuỗi làm điều kiện, chuỗi rỗng `\"\"` là sai, còn chuỗi chỉ có một dấu cách `\" \"` vẫn là đúng."},{"heading":"Dữ liệu từ `input()`","body":"`input()` luôn trả về chuỗi, kể cả khi người dùng gõ số. Muốn so sánh với số thì đổi sang số trước bằng `int()` hoặc `float()`. So một chuỗi với một số sẽ gây `TypeError`."},{"heading":"Thử ở điểm biên","body":"Khi viết một điều kiện có ngưỡng, hãy thử ba giá trị: đúng bằng ngưỡng, nhỏ hơn một chút và lớn hơn một chút. Chọn nhầm `<` với `<=` chỉ lộ ra ở đúng điểm bằng."}],"mistakes":[{"code":"tuoi = \"16\"\nprint(tuoi < 18)","explain":"Giá trị trong ngoặc kép là chuỗi, và `input()` cũng trả về chuỗi. Python không so chuỗi với số. Đổi sang `int` trước khi so."},{"code":"gioi_han = 90\ntoc_do = 90\nprint(toc_do < gioi_han)","explain":"Luật \"không vượt giới hạn\" gồm cả điểm bằng. `<` bỏ mất điểm đó, nên phải dùng `<=`."},{"code":"diem = 9\nif diem >= 5:\n    print(\"Dat\")\nelif diem >= 8:\n    print(\"Gioi\")","explain":"Nhánh `diem >= 5` đứng trước nên bắt luôn điểm 9, và nhánh \"Gioi\" không bao giờ chạy. Đặt điều kiện hẹp lên trước."},{"code":"tuoi = 10\nif tuoi < 18:\n    ve = \"Tre em\"\nelse:\n    ve = \"Nguoi lon\"\n    print(ve)","explain":"Dòng `print(ve)` thụt vào nên thuộc khối `else` và chỉ chạy khi `tuoi` từ 18 trở lên. Bỏ thụt lề để dòng in nằm sau khối."},{"code":"co_ve = False\ndu_tuoi = True\nco_nguoi_lon = True\nprint(co_ve and du_tuoi or co_nguoi_lon)","explain":"Python tính `and` trước `or`, nên điều kiện thành `(co_ve and du_tuoi) or co_nguoi_lon`. Muốn bắt buộc có vé thì viết `co_ve and (du_tuoi or co_nguoi_lon)`."},{"code":"mon = \"Toan\"\nif mon = \"Toan\":\n    print(\"Thi sang\")","explain":"Trong điều kiện, phép so sánh bằng phải dùng `==`. Một dấu `=` là phép gán, Python không chấp nhận nó ở đây."},{"code":"diem = 9\nif diem >= 8:\nprint(\"Gioi\")","explain":"Thân của `if` phải thụt lề. Không có dòng nào thụt vào, Python báo `if` thiếu khối lệnh."}],"next":"Chương 3: Mê cung Máy chủ. Trong các hành lang ở đó, cảm biến quét đi quét lại không dứt. Bạn sẽ cần vòng lặp để mã làm lại một việc nhiều lần."}}', revision = 2, updated_at = '2026-11-06T00:00:00.000Z', updated_by = 'migration' WHERE doc_id = 'level:2.7' AND revision = 1 AND updated_by = 'migration';
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.7' AND revision = 2 AND updated_at = '2026-11-06T00:00:00.000Z' AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;

